{"result":"1|package com.oms.dashboard;
2|
3|import java.sql.Timestamp;
4|import java.time.Instant;
5|import java.util.Optional;
6|import org.springframework.dao.DuplicateKeyException;
7|import org.springframework.dao.EmptyResultDataAccessException;
8|import org.springframework.jdbc.core.JdbcTemplate;
9|import org.springframework.stereotype.Repository;
10|
11|/**
12| * JDBC-backed dashboard projection. Uses an update-first, insert-on-miss upsert
13| * guarded by the primary key so the same code works on both the embedded H2
14| * default and PostgreSQL without dialect-specific {@code ON CONFLICT} /
15| * {@code MERGE} syntax — and stays correct under concurrent first writes.
16| */
17|@Repository
18|public class JdbcDashboardRepository implements DashboardRepository {
19|
20|  private final JdbcTemplate jdbc;
21|
22|  public JdbcDashboardRepository(JdbcTemplate jdbc) {
23|    this.jdbc = jdbc;
24|  }
25|
26|  @Override
27|  public void upsert(DashboardStatus status) {
28|    Timestamp updatedAt = Timestamp.from(status.updatedAt());
29|    if (update(status.orderId(), status.status(), updatedAt) == 0) {
30|      // Row absent: try to insert. If a concurrent writer inserted it first, the
31|      // primary key rejects our insert (DuplicateKeyException) and we fall back
32|      // to an update — so the write is never silently lost to a race.
33|      try {
34|        insert(status.orderId(), status.status(), updatedAt);
35|      } catch (DuplicateKeyException e) {
36|        update(status.orderId(), status.status(), updatedAt);
37|      }
38|    }
39|  }
40|
41|  @Override
42|  public boolean insertIfAbsent(DashboardStatus status) {
43|    try {
44|      insert(status.orderId(), status.status(), Timestamp.from(status.updatedAt()));
45|      return true;
46|    } catch (DuplicateKeyException e) {
47|      return false;
48|    }
49|  }
50|
51|  @Override
52|  public void delete(String orderId) {
53|    jdbc.update("DELETE FROM orders_dashboard WHERE order_id = ?", orderId);
54|  }
55|
56|  private int update(String orderId, String status, Timestamp updatedAt) {
57|    return jdbc.update(
58|        "UPDATE orders_dashboard SET status = ?, updated_at = ? WHERE order_id = ?",
59|        status,
60|        updatedAt,
61|        orderId);
62|  }
63|
64|  private void insert(String orderId, String status, Timestamp updatedAt) {
65|    jdbc.update(
66|        "INSERT INTO orders_dashboard (order_id, status, updated_at) VALUES (?, ?, ?)",
67|        orderId,
68|        status,
69|        updatedAt);
70|  }
71|
72|  @Override
73|  public Optional<DashboardStatus> find(String orderId) {
74|    try {
75|      DashboardStatus row =
76|          jdbc.queryForObject(
77|              "SELECT order_id, status, updated_at FROM orders_dashboard WHERE order_id = ?",
78|              (rs, n) ->
79|                  new DashboardStatus(
80|                      rs.getString("order_id"),
81|                      rs.getString("status"),
82|                      toInstant(rs.getTimestamp("updated_at"))),
83|              orderId);
84|      return Optional.ofNullable(row);
85|    } catch (EmptyResultDataAccessException e) {
86|      return Optional.empty();
87|    }
88|  }
89|
90|  private static Instant toInstant(Timestamp ts) {
91|    return ts == null ? null : ts.toInstant();
92|  }
93|}
