41|/**
42| * HTTP gateway — the Camunda parity of the Temporal {@code api/ApiApp.go}.
43| *
44| * <pre>
45| *   POST /orders            -> start an order-processing process instance
46| *   POST /orders/correction -> publish SupportCorrection message
47| *   POST /orders/payment    -> publish CapturePayment message
48| *   POST /orders/cancel     -> publish CancelOrder message
49| *   GET  /orders/status     -> read the dashboard projection
50| * </pre>
51| *
52| * <p>Temporal used synchronous validated Workflow Updates to reject illegal
53| * correction/payment attempts with HTTP 409. Zeebe messages are fire-and-forget
54| * with no validating handler, so that 409 behaviour is reproduced here at the
55| * API layer by validating against the dashboard projection before publishing —
56| * the one design accommodation called out in the migration notes.
57| */
58|@RestController
59|@RequestMapping("/orders")
60|public class OrderController {
61|
62|  private static final Logger LOG = LoggerFactory.getLogger(OrderController.class);
63|
64|  /** Messages buffer in Zeebe until the instance reaches the catch, up to TTL. */
65|  private static final Duration MESSAGE_TTL = Duration.ofDays(30);
66|
67|  private final ZeebeClient zeebe;
68|  private final DashboardRepository dashboardRepo;
69|
70|  public OrderController(ZeebeClient zeebe, DashboardRepository dashboardRepo) {
71|    this.zeebe = zeebe;
72|    this.dashboardRepo = dashboardRepo;
73|  }
74|
75|  // ------------------------------------------------------------ POST /orders
76|
77|  @PostMapping
78|  public ResponseEntity<?> createOrder(@RequestBody CommerceWebhookRequest req) {
79|    if (isBlank(req.orderId())) {
80|      return badRequest("order_id is required");
81|    }
82|
83|    // Atomic idempotency claim (parity of ALLOW_DUPLICATE_FAILED_ONLY): the
84|    // projection's primary key is a per-order lock. Exactly one concurrent
85|    // create wins the insert and starts the instance; the rest get 409. The
86|    // claim also seeds ORDER_RECEIVED so an immediate GET /orders/status doesn't
87|    // race the first update-dashboard job.
88|    boolean claimed =
89|        dashboardRepo.insertIfAbsent(
90|            new DashboardStatus(req.orderId(), OrderStatus.ORDER_RECEIVED.name(), Instant.now()));
91|    if (!claimed) {
92|      return conflict("order workflow already exists");
93|    }
94|
95|    OrderInput order =
96|        new OrderInput(
97|            req.orderId(), req.customerId(), req.items(), req.totalAmount(), req.currency());
98|
99|    Map<String, Object> variables = new HashMap<>();
100|    variables.put(VAR_ORDER_ID, req.orderId());
101|    variables.put(VAR_ORDER, order);
102|
103|    ProcessInstanceEvent instance;
104|    try {
105|      instance =
106|          zeebe
107|              .newCreateInstanceCommand()
108|              .bpmnProcessId(PROCESS_ID)
109|              .latestVersion()
110|              .variables(variables)
111|              .send()
112|              .join();
113|    } catch (RuntimeException e) {
114|      // Release the claim so the order can be retried rather than being wedged
115|      // behind a claim row that has no running instance.
116|      LOG.error("failed to start process for order {}; releasing claim", req.orderId(), e);
117|      safeReleaseClaim(req.orderId());
118|      return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
119|          .body(new ErrorResponse("failed to start order workflow"));
120|    }
121|
122|    return ResponseEntity.accepted()
123|        .body(new StartWorkflowResponse(instance.getProcessInstanceKey(), req.orderId()));
124|  }
125|
126|  // ------------------------------------------------- POST /orders/correction
127|
128|  @PostMapping("/correction")
129|  public ResponseEntity<?> correction(@RequestBody CorrectionWebhookRequest req) {
130|    if (isBlank(req.orderId())) {
131|      return badRequest("order_id is required");
132|    }
133|
134|    OrderStatus status = currentStatus(req.orderId());
135|    if (status == null) {
136|      return notFound("order not found");
137|    }
138|    if (isTerminal(status)) {
139|      return conflict("workflow is already in a terminal state");
140|    }
141|    if (status != OrderStatus.AWAITING_CORRECTION) {
142|      return conflict("correction not allowed in current state");
143|    }
144|
145|    publish(MSG_SUPPORT_CORRECTION, req.orderId(), Map.of(VAR_CORRECTION_ITEMS, req.items()));
146|    return ResponseEntity.noContent().build();
147|  }
148|
149|  // ---------------------------------------------------- POST /orders/payment
150|
151|  @PostMapping("/payment")
152|  public ResponseEntity<?> payment(@RequestBody PaymentWebhookRequest req) {
153|    if (isBlank(req.orderId())) {
154|      return badRequest("order_id is required");
155|    }
156|    if (isBlank(req.rrn())) {
157|      return badRequest("rrn is required");
158|    }
159|
160|    OrderStatus status = currentStatus(req.orderId());
161|    if (status == null) {
162|      return notFound("order not found");
163|    }
164|    if (isTerminal(status)) {
165|      return conflict("workflow is already in a terminal state");
166|    }
167|    if (status == OrderStatus.PAYMENT_CAPTURED) {
168|      return conflict("payment already captured");
169|    }
170|
171|    PaymentInput payment =
172|        new PaymentInput(
173|            req.rrn(), req.amount(), req.currency(), req.paymentMethod(), req.paidAt());
174|    publish(MSG_CAPTURE_PAYMENT, req.orderId(), Map.of(VAR_PAYMENT, payment));
175|    return ResponseEntity.noContent().build();
176|  }
177|
178|  // ----------------------------------------------------- POST /orders/cancel
179|
180|  @PostMapping("/cancel")
181|  public ResponseEntity<?> cancel(@RequestBody CancelWebhookRequest req) {
182|    if (isBlank(req.orderId())) {
183|      return badRequest("order_id is required");
184|    }
185|    publish(MSG_CANCEL_ORDER, req.orderId(), Map.of());
186|    return ResponseEntity.noContent().build();
187|  }
188|
189|  // ------------------------------------------------------ GET /orders/status
190|
191|  @GetMapping("/status")
192|  public ResponseEntity<?> status(@RequestParam("order_id") String orderId) {
193|    if (isBlank(orderId)) {
194|      return badRequest("order_id query parameter is required");
195|    }
196|    return dashboardRepo
197|        .find(orderId)
198|        .<ResponseEntity<?>>map(
199|            row ->
200|                ResponseEntity.ok(
201|                    new OrderStatusResponse(row.orderId(), OrderStatus.fromString(row.status()))))
202|        .orElseGet(() -> notFound("order not found"));
203|  }
204|
205|  // --------------------------------------------------------------- internals
206|
207|  private OrderStatus currentStatus(String orderId) {
208|    return dashboardRepo
209|        .find(orderId)
210|        .map(row -> OrderStatus.fromString(row.status()))
211|        .orElse(null);
212|  }
213|
214|  private static boolean isTerminal(OrderStatus status) {
215|    return switch (status) {
216|      case CANCELLED, EXPIRED, FULFILLED, FAILED_PAYMENT -> true;
217|      default -> false;
218|    };
219|  }
220|
221|  private void publish(String messageName, String orderId, Map<String, Object> variables) {
222|    zeebe
223|        .newPublishMessageCommand()
224|        .messageName(messageName)
225|        .correlationKey(orderId)
226|        .timeToLive(MESSAGE_TTL)
227|        .variables(variables)
228|        .send()
229|        .join();
230|  }
231|
232|  private void safeReleaseClaim(String orderId) {
233|    try {
234|      dashboardRepo.delete(orderId);
235|    } catch (RuntimeException e) {
236|      LOG.warn("failed to release idempotency claim for order {}", orderId, e);
237|    }
238|  }
239|
240|  private static boolean isBlank(String s) {
241|    return s == null || s.isBlank();
242|  }
243|
244|  private static ResponseEntity<ErrorResponse> badRequest(String msg) {
245|    return ResponseEntity.badRequest().body(new ErrorResponse(msg));
246|  }
247|
248|  private static ResponseEntity<ErrorResponse> conflict(String msg) {
249|    return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse(msg));
250|  }
251|
252|  private static ResponseEntity<ErrorResponse> notFound(String msg) {
253|    return ResponseEntity.status(HttpStatus.NOT_FOUND).body(new ErrorResponse(msg));
254|  }
