{"content": "package workflows

import (
	"time"

	"go.temporal.io/sdk/temporal"
	"go.temporal.io/sdk/workflow"

	"shinro-migration/oms-camunda-application/activities"
	"shinro-migration/oms-camunda-application/shared"
)

// OrderTTL is the 30-day order lifetime (BPMN Start_TTL timer,
// timeDuration=PT720H) as a Go duration constant.
const OrderTTL = shared.OrderTTL

// OrderProcessingWorkflow reimplements Camunda process "order-processing"
// (models/order-processing.bpmn) as a Temporal workflow.
//
// BPMN → Temporal mapping:
//
//   - service tasks (update-dashboard / validate-order / validate-payment /
//     enrich-order / publish-fulfillment) → activities with the per-task
//     RetryPolicy from the BPMN "retries" attribute (and the worker md
//     "Suggested retry policy" lines);
//   - message catch events (Catch_Payment, Catch_Correction) → signal
//     channels on the same message names, correlated by workflow id
//     (parity of zeebe correlationKey=orderId);
//   - boundary error events (Bnd_InvalidOrder → correction loop,
//     Bnd_InvalidPayment → back to the payment wait) → typed non-retryable
//     application errors (codes INVALID_ORDER / INVALID_PAYMENT) caught
//     inline where the boundary was attached;
//   - interrupting message event subprocess "Cancellation"
//     (Message_CancelOrder, terminate) → workflow.Go goroutine on the
//     CancelOrder signal: dashboard CANCELLED, then terminate;
//   - interrupting timer event subprocess "Order TTL (30 days)"
//     (PT720H, terminate) → workflow.Go goroutine: 720h timer, dashboard
//     EXPIRED, then terminate.
//
// The terminate end events (End_Cancelled, End_Expired) map to
// workflow.CancelExternalWorkflow on the workflow's own context, the
// standard Temporal pattern for self-termination.
func OrderProcessingWorkflow(ctx workflow.Context, in shared.OrderProcessingInput) (shared.OrderProcessingResult, error) {
	logger := workflow.GetLogger(ctx).With("workflow", "order-processing", "orderId", in.OrderId)

	// Base activity options: a generous start-to-close bound. Retry policies
	// are set per activity call from the BPMN task "retries" attributes.
	base := workflow.ActivityOptions{StartToCloseTimeout: 5 * time.Minute}
	// update-dashboard / enrich-order / publish-fulfillment / validate-order
	// have retries="2147483647" in the BPMN (unbounded) — mirror with no
	// MaximumAttempts cap; the SDK default exponential backoff still applies.
	unlimited := base // retryPolicy: maximumAttempts=2147483647 -> no cap
	// validate-payment has retries="5".
	validatePayment := base
	validatePayment.RetryPolicy = &temporal.RetryPolicy{MaximumAttempts: 5} // retryPolicy: maximumAttempts=5
	ctx = workflow.WithActivityOptions(ctx, unlimited)

	orderID := in.OrderId
	order := in.Order

	// --- interrupting subprocess "Cancellation" (Message_CancelOrder) ---
	cancelSignal := workflow.GetSignalChannel(ctx, shared.SignalCancelOrder)
	cancelled := workflow.NewFuture(ctx)
	var cancelErr error
	workflow.Go(ctx, func(gctx workflow.Context) {
		_ = cancelSignal.Receive(gctx, nil)
		logger.Info("cancel order signal received")
		// Task_UpdateCancelled: Dashboard: CANCELLED.
		err := workflow.ExecuteActivity(gctx, activities.UpdateDashboard,
			shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusCancelled}).Get(gctx, nil)
		if err != nil {
			cancelErr = err
			cancelled.Set(nil, err)
			return
		}
		// End_Cancelled: terminate event → self-terminate.
		cancelled.Set(nil, workflow.CancelExternalWorkflow(gctx, workflow.GetInfo(gctx).WorkflowExecution.ID, "", true))
	})

	// --- interrupting timer subprocess "Order TTL (30 days)" (PT720H) ---
	ttlFired := workflow.NewFuture(ctx)
	ttlErr := workflow.NewTimer(ctx, OrderTTL)
	workflow.Go(ctx, func(gctx workflow.Context) {
		_ = ttlErr // timer elapsed
		logger.Info("order TTL (30 days) elapsed")
		// Task_UpdateExpired: Dashboard: EXPIRED.
		err := workflow.ExecuteActivity(gctx, activities.UpdateDashboard,
			shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusExpired}).Get(gctx, nil)
		if err != nil {
			ttlErr = err
			ttlFired.Set(nil, err)
			return
		}
		// End_Expired: terminate event → self-terminate.
		ttlFired.Set(nil, workflow.CancelExternalWorkflow(gctx, workflow.GetInfo(gctx).WorkflowExecution.ID, "", true))
	})

	payment := *shared.PaymentInput{} // zero value until CapturePayment arrives

	// Task_UpdateReceived: Dashboard: ORDER_RECEIVED
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusOrderReceived}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}

	for {
		// Task_ValidateOrder: Validate order (Commerce API) — boundary
		// Bnd_InvalidOrder (error INVALID_ORDER) drives the correction loop.
		var validateOut shared.ValidateOrderOutput
		err := workflow.ExecuteActivity(ctx, activities.ValidateOrder,
			shared.ValidateOrderInput{Order: order, CorrectionItems: nil}).Get(ctx, &validateOut)
		if err != nil {
			if isBpmnError(err, shared.ErrInvalidOrder) {
				logger.Info("order validation failed; awaiting correction", "reason", err.Error())
				// Task_AwaitCorrectionStatus: Dashboard: AWAITING_CORRECTION
				if derr := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
					shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusAwaitingCorrection}).Get(ctx, nil); derr != nil {
					return shared.OrderProcessingResult{}, derr
				}
				// Catch_Correction: await Message_SupportCorrection, then
				// re-enter Task_ValidateOrder with the corrected items.
				var correction shared.SupportCorrectionSignal
				if serr := workflow.GetSignalChannel(ctx, shared.SignalSupportCorrection).Receive(ctx, &correction); serr != nil {
					return shared.OrderProcessingResult{}, serr
				}
				order = &shared.OrderInput{
					OrderId:     order.OrderId,
					CustomerId:  order.CustomerId,
					Items:       correction.Items,
					TotalAmount: order.TotalAmount,
					Currency:    order.Currency,
				}
				// The correction is consumed: re-validate with it.
				retry := unlimited
				retryCtx := workflow.WithActivityOptions(ctx, retry)
				// Re-enter Task_ValidateOrder — on success the consumed
				// correction is cleared (next loop iteration passes nil).
				continue
			}
			return shared.OrderProcessingResult{}, err
		}
		order = validateOut.Order

		// Task_UpdatePaymentPending: Dashboard: PAYMENT_PENDING
		if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
			shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusPaymentPending}).Get(ctx, nil); err != nil {
			return shared.OrderProcessingResult{}, err
		}

		// Catch_Payment: await Message_CapturePayment (also the landing
		// point of Bnd_InvalidPayment below).
		var capSig shared.CapturePaymentSignal
		if serr := workflow.GetSignalChannel(ctx, shared.SignalCapturePayment).Receive(ctx, &capSig); serr != nil {
			return shared.OrderProcessingResult{}, serr
		}
		payment = *capSig.Payment

		// Task_ValidatePayment: Validate payment RRN — boundary
		// Bnd_InvalidPayment (error INVALID_PAYMENT) loops back to the
		// Catch_Payment wait.
		var payOut shared.ValidatePaymentOutput
		err = workflow.ExecuteActivity(workflow.WithActivityOptions(ctx, validatePayment),
			activities.ValidatePayment,
			shared.ValidatePaymentInput{Order: order, Payment: &payment}).Get(ctx, &payOut)
		if err != nil {
			if isBpmnError(err, shared.ErrInvalidPayment) {
				logger.Info("payment validation failed; awaiting new payment", "reason", err.Error())
				// Bnd_InvalidPayment → Flow_bnd_catchpay → Catch_Payment.
				continue
			}
			return shared.OrderProcessingResult{}, err
		}
		payment = *payOut.Payment
		break
	}

	// Task_UpdateCaptured: Dashboard: PAYMENT_CAPTURED
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusPaymentCaptured}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}

	// Task_Enrich: Enrich with PIM
	var enrichOut shared.EnrichOrderOutput
	if err := workflow.ExecuteActivity(ctx, activities.EnrichOrder,
		shared.EnrichOrderInput{Order: order}).Get(ctx, &enrichOut); err != nil {
		return shared.OrderProcessingResult{}, err
	}
	order = enrichOut.Order

	// Task_Publish: Publish to fulfillment
	if _, err := workflow.ExecuteActivity(ctx, activities.PublishFulfillment,
		shared.PublishFulfillmentInput{Order: order, Payment: &payment}); err != nil {
		return shared.OrderProcessingResult{}, err
	}

	// Task_UpdateFulfilled: Dashboard: FULFILLED
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusFulfilled}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}

	// EndEvent_Done: Order fulfilled
	return shared.OrderProcessingResult{
		OrderId: orderID,
		Outcome: "FULFILLED",
		Order:   order,
		Payment: &payment,
	}, nil
}

// isBpmnError reports whether err is a non-retryable application error with
// the given BPMN error code (the Go equivalent of a Zeebe boundary error
// event on errorCode).
func isBpmnError(err error, code string) bool {
	ae, ok := err.(*temporal.ApplicationError)
	return ok && ae.Type() == code
}
", "path": "workflows/order_processing.go"}

{"content": "package workflows

import (
	"time"

	"go.temporal.io/sdk/temporal"
	"go.temporal.io/sdk/workflow"

	"shinro-migration/oms-camunda-application/activities"
	"shinro-migration/oms-camunda-application/shared"
)

// OrderProcessingWorkflow reimplements Camunda process "order-processing"
// (models/order-processing.bpmn) as a Temporal workflow.
//
// BPMN → Temporal mapping:
//
//   - service tasks (update-dashboard / validate-order / validate-payment /
//     enrich-order / publish-fulfillment) → activities; retry policies come
//     from the BPMN task "retries" attributes (validate-payment=5, all other
//     service tasks 2147483647 ≈ unbounded);
//   - message catch events (Catch_Payment, Catch_Correction) → signal
//     channels on the same message names, correlated by workflow id
//     (parity of the zeebe correlationKey=orderId — the workflow id is
//     derived from the order id by the starter);
//   - boundary error events → typed non-retryable application errors:
//     Bnd_InvalidOrder (code INVALID_ORDER) on Task_ValidateOrder drives
//     the correction loop; Bnd_InvalidPayment (code INVALID_PAYMENT) on
//     Task_ValidatePayment loops back to the Catch_Payment wait;
//   - interrupting message event subprocess "Cancellation"
//     (Message_CancelOrder → Dashboard CANCELLED → terminate) → the
//     main flow checks for a buffered CancelOrder signal between every
//     blocking step and, if present, runs the cancellation sequence and
//     self-terminates;
//   - interrupting timer event subprocess "Order TTL (30 days)"
//     (PT720H → Dashboard EXPIRED → terminate) → a workflow.NewTimer(720h)
//     future checked at the same points; on expiry the flow runs the
//     expiry sequence and self-terminates.
//
// Both terminate end events (End_Cancelled, End_Expired) map to
// workflow.CancelExternalWorkflow on the workflow's own execution — the
// standard Temporal pattern for self-termination.
func OrderProcessingWorkflow(ctx workflow.Context, in shared.OrderProcessingInput) (shared.OrderProcessingResult, error) {
	logger := workflow.GetLogger(ctx).With("workflow", "order-processing", "orderId", in.OrderId)

	// Base activity options: a generous start-to-close bound. The four
	// "unbounded" service tasks keep the SDK default retry policy (no
	// MaximumAttempts cap — parity of retries="2147483647"); validate-payment
	// gets MaximumAttempts: 5 (parity of retries="5").
	base := workflow.ActivityOptions{StartToCloseTimeout: 5 * time.Minute}
	validatePayment := base
	validatePayment.RetryPolicy = &temporal.RetryPolicy{MaximumAttempts: 5}
	ctx = workflow.WithActivityOptions(ctx, base)

	orderID := in.OrderId
	order := in.Order

	// --- interrupting subprocess "Cancellation" (Message_CancelOrder) ---
	cancelSignal := workflow.GetSignalChannel(ctx, shared.SignalCancelOrder)

	// --- interrupting timer subprocess "Order TTL (30 days)" (PT720H) ---
	// workflow.NewTimer is deterministic; the future completes 720h after
	// start (earlier wall-clock expiry under replay is clamped to the same
	// scheduled time).
	ttlFired := workflow.NewTimer(ctx, shared.OrderTTL)

	// checkInterrupts runs the interrupting subprocesses that share a start
	// point in BPMN: whichever trigger (cancel signal / TTL timer) is ready
	// wins, exactly like the Zeebe event subprocesses interrupting the main
	// flow. Returns (terminated, result, error).
	checkInterrupts := func() (bool, shared.OrderProcessingResult, error) {
		if !cancelSignal.HasReceive(ctx) {
			if !ttlFired.IsReady() {
				return false, shared.OrderProcessingResult{}, nil
			}
			logger.Info("order TTL (30 days) elapsed")
			// Task_UpdateExpired: Dashboard: EXPIRED
			if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
				shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusExpired}).Get(ctx, nil); err != nil {
				return false, shared.OrderProcessingResult{}, err
			}
			// End_Expired: terminate event → self-terminate.
			if err := workflow.CancelExternalWorkflow(ctx, workflow.GetInfo(ctx).WorkflowExecution.ID, "", true); err != nil {
				return false, shared.OrderProcessingResult{}, err
			}
			return true, shared.OrderProcessingResult{}, nil
		}
		// CancelOrder arrived (buffered while we were between steps).
		var cancel shared.CancelOrderSignal
		_ = cancelSignal.Receive(ctx, &cancel)
		logger.Info("cancel order signal received", "reason", cancel.Reason)
		// Task_UpdateCancelled: Dashboard: CANCELLED
		if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
			shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusCancelled}).Get(ctx, nil); err != nil {
			return false, shared.OrderProcessingResult{}, err
		}
		// End_Cancelled: terminate event → self-terminate.
		if err := workflow.CancelExternalWorkflow(ctx, workflow.GetInfo(ctx).WorkflowExecution.ID, "", true); err != nil {
			return false, shared.OrderProcessingResult{}, err
		}
		return true, shared.OrderProcessingResult{}, nil
	}

	payment := *shared.PaymentInput{} // zero value until CapturePayment arrives
	var correctionItems []shared.OrderItem // pending SupportCorrection, cleared once consumed

	// Task_UpdateReceived: Dashboard: ORDER_RECEIVED
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusOrderReceived}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}
	if done, _, err := checkInterrupts(); done {
		return shared.OrderProcessingResult{}, err
	}

	for {
		// Task_ValidateOrder: Validate order (Commerce API). The activity
		// applies correctionItems itself (parity of applyCorrection) and
		// throws BPMN error INVALID_ORDER on business failure.
		var validateOut shared.ValidateOrderOutput
		err := workflow.ExecuteActivity(ctx, activities.ValidateOrder,
			shared.ValidateOrderInput{Order: order, CorrectionItems: correctionItems}).Get(ctx, &validateOut)
		if err != nil {
			if isBpmnError(err, shared.ErrInvalidOrder) {
				logger.Info("order validation failed; awaiting correction", "reason", err.Error())
				// Task_AwaitCorrectionStatus: Dashboard: AWAITING_CORRECTION
				if derr := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
					shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusAwaitingCorrection}).Get(ctx, nil); derr != nil {
					return shared.OrderProcessingResult{}, derr
				}
				// Catch_Correction: await Message_SupportCorrection, then
				// re-enter Task_ValidateOrder with the corrected items.
				var correction shared.SupportCorrectionSignal
				if serr := workflow.GetSignalChannel(ctx, shared.SignalSupportCorrection).Receive(ctx, &correction); serr != nil {
					return shared.OrderProcessingResult{}, serr
				}
				correctionItems = correction.Items
				// A signal could have raced in while we were validating.
				if done, _, ierr := checkInterrupts(); done {
					return shared.OrderProcessingResult{}, ierr
				}
				continue
			}
			return shared.OrderProcessingResult{}, err
		}
		order = validateOut.Order
		// The consumed correction is cleared (next validation passes nil —
		// parity of newCompleteCommand writing correctionItems=null).
		correctionItems = nil

		// Task_UpdatePaymentPending: Dashboard: PAYMENT_PENDING
		if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
			shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusPaymentPending}).Get(ctx, nil); err != nil {
			return shared.OrderProcessingResult{}, err
		}
		if done, _, err := checkInterrupts(); done {
			return shared.OrderProcessingResult{}, err
		}

		// Catch_Payment: await Message_CapturePayment (also the landing
		// point of the Bnd_InvalidPayment boundary below).
		var capSig shared.CapturePaymentSignal
		if serr := workflow.GetSignalChannel(ctx, shared.SignalCapturePayment).Receive(ctx, &capSig); serr != nil {
			return shared.OrderProcessingResult{}, serr
		}
		payment = *capSig.Payment

		// Task_ValidatePayment: Validate payment RRN — boundary
		// Bnd_InvalidPayment (error INVALID_PAYMENT) loops back to the
		// Catch_Payment wait; the next CapturePayment message overwrites
		// the stale payment.
		var payOut shared.ValidatePaymentOutput
		err = workflow.ExecuteActivity(workflow.WithActivityOptions(ctx, validatePayment),
			activities.ValidatePayment,
			shared.ValidatePaymentInput{Order: order, Payment: &payment}).Get(ctx, &payOut)
		if err != nil {
			if isBpmnError(err, shared.ErrInvalidPayment) {
				logger.Info("payment validation failed; awaiting new payment", "reason", err.Error())
				// Bnd_InvalidPayment → Flow_bnd_catchpay → Catch_Payment.
				if done, _, ierr := checkInterrupts(); done {
					return shared.OrderProcessingResult{}, ierr
				}
				continue
			}
			return shared.OrderProcessingResult{}, err
		}
		payment = *payOut.Payment
		break
	}

	// Task_UpdateCaptured: Dashboard: PAYMENT_CAPTURED
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusPaymentCaptured}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}
	if done, _, err := checkInterrupts(); done {
		return shared.OrderProcessingResult{}, err
	}

	// Task_Enrich: Enrich with PIM
	var enrichOut shared.EnrichOrderOutput
	if err := workflow.ExecuteActivity(ctx, activities.EnrichOrder,
		shared.EnrichOrderInput{Order: order}).Get(ctx, &enrichOut); err != nil {
		return shared.OrderProcessingResult{}, err
	}
	order = enrichOut.Order

	// Task_Publish: Publish to fulfillment
	if _, err := workflow.ExecuteActivity(ctx, activities.PublishFulfillment,
		shared.PublishFulfillmentInput{Order: order, Payment: &payment}); err != nil {
		return shared.OrderProcessingResult{}, err
	}

	// Task_UpdateFulfilled: Dashboard: FULFILLED
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusFulfilled}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}

	// EndEvent_Done: Order fulfilled
	return shared.OrderProcessingResult{
		OrderId: orderID,
		Outcome: "FULFILLED",
		Order:   order,
		Payment: &payment,
	}, nil
}

// isBpmnError reports whether err is an application error carrying the given
// BPMN error code (the Go equivalent of a Zeebe boundary error event matched
// on errorCode).
func isBpmnError(err error, code string) bool {
	ae, ok := err.(*temporal.ApplicationError)
	return ok && ae.Type() == code
}
