// zzFailingWorkflow runs a mocked activity that fails with a typed
// application error, then returns the error to fail the workflow.
func zzFailingWorkflow(ctx workflow.Context) error {
	ctx = workflow.WithActivityOptions(ctx, workflow.ActivityOptions{StartToCloseTimeout: time.Minute})
	var out string
	err := workflow.ExecuteActivity(ctx, zzEcho, "x").Get(ctx, &out)
	return err
}

// zzEcho is a trivial activity used only by the probe test.
func zzEcho(_ context_placeholder, _ string) (string, error) { return "", temporal.NewNonRetryableApplicationError("boom", "BOOM", nil) }

// TestZZErrorChainProbe prints the type and exported method set of the
// error surfaced by GetWorkflowError, so we can see how this SDK build
// chains the application error.
func TestZZErrorChainProbe(t *testing.T) {
	env := newTestEnv()
	env.SetTestTimeout(5 * time.Second)
	env.OnActivity(zzEcho, mockAny, "x").
		Return("", temporal.NewNonRetryableApplicationError("boom", "BOOM", nil))
	env.ExecuteWorkflow(zzFailingWorkflow)
	err := env.GetWorkflowError()
	if err == nil {
		t.Fatal("expected an error")
	}
	v := reflect.ValueOf(err)
	for i := 0; i < v.Type().NumMethod(); i++ {
		t.Logf("method: %s", v.Type().Method(i).Name)
	}
	t.Logf("type: %T", err)
	t.Logf("message: %v", err)
	// Try the standard chains.
	var appErr *temporal.ApplicationError
	if ok := isType(err, &appErr); ok {
		t.Logf("errors.As(*temporal.ApplicationError) ok, type=%s", appErr.Type())
	}
	fmt.Println("probe done")
}

// isType mirrors errors.As without importing errors in two places.
func isType(err error, target *temporal.ApplicationError) bool {
	for err != nil {
		if te, ok := err.(*temporal.ApplicationError); ok {
			*target = te
			return true
		}
		u, ok := err.(interface{ Unwrap() error })
		if !ok {
			return false
		}
		err = u.Unwrap()
	}
	return false
}
