import (
	"testing"
	"time"

	"go.temporal.io/sdk/workflow"

	"shinro-migration/oms-camunda-application/activities"
	"shinro-migration/oms-camunda-application/shared"
)

// zzInterruptWorkflow mirrors the interrupting-subprocess pattern of
// OrderProcessingWorkflow: a goroutine receives a signal and sets a flag;
// the main flow does one activity, then Await(flag).
func zzInterruptWorkflow(ctx workflow.Context) error {
	ctx = workflow.WithActivityOptions(ctx, workflow.ActivityOptions{StartToCloseTimeout: time.Minute})
	flag := false
	workflow.Go(ctx, func(gctx workflow.Context) {
		var sig shared.CancelOrderSignal
		workflow.GetSignalChannel(gctx, shared.SignalCancelOrder).Receive(gctx, &sig)
		flag = true
	})

	var out shared.UpdateDashboardOutput
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: "ord-1", Status: shared.StatusOrderReceived}).Get(ctx, &out); err != nil {
		return err
	}
	workflow.Await(ctx, func() bool { return flag })
	return nil
}

// TestZZInterruptProbe checks that a signal received in a workflow.Go
// goroutine wakes the main flow's workflow.Await in this SDK build.
func TestZZInterruptProbe(t *testing.T) {
	env := newTestEnv()
	env.SetTestTimeout(5 * time.Second)
	env.OnActivity(activities.UpdateDashboard, mock.Anything,
		shared.UpdateDashboardInput{OrderId: "ord-1", Status: shared.StatusOrderReceived}).
		Return(shared.UpdateDashboardOutput{Applied: true}, nil)

	env.RegisterDelayedCallback(func() {
		env.SignalWorkflow(shared.SignalCancelOrder,
			shared.CancelOrderSignal{OrderId: "ord-1", Reason: "probe"})
	}, time.Millisecond)

	env.ExecuteWorkflow(zzInterruptWorkflow)
	err := env.GetWorkflowError()
	t.Logf("completed=%v err=%v", env.IsWorkflowCompleted(), err)
	if err != nil {
		t.Fatalf("probe workflow failed: %v", err)
	}
}

// zzTTLWorkflow mirrors the TTL pattern: a goroutine waits on a timer and
// sets a flag; the main flow does one activity, then Await(flag).
func zzTTLWorkflow(ctx workflow.Context) error {
	ctx = workflow.WithActivityOptions(ctx, workflow.ActivityOptions{StartToCloseTimeout: time.Minute})
	fired := false
	workflow.Go(ctx, func(gctx workflow.Context) {
		if err := workflow.NewTimer(gctx, time.Hour).Get(gctx, nil); err != nil {
			return
		}
		fired = true
	})

	var out shared.UpdateDashboardOutput
	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: "ord-1", Status: shared.StatusOrderReceived}).Get(ctx, &out); err != nil {
		return err
	}
	workflow.Await(ctx, func() bool { return fired })
	return nil
}

// TestZZTTLProbe checks that a timer fired in a workflow.Go goroutine
// wakes the main flow's workflow.Await in this SDK build.
func TestZZTTLProbe(t *testing.T) {
	env := newTestEnv()
	env.SetTestTimeout(5 * time.Second)
	env.OnActivity(activities.UpdateDashboard, mock.Anything,
		shared.UpdateDashboardInput{OrderId: "ord-1", Status: shared.StatusOrderReceived}).
		Return(shared.UpdateDashboardOutput{Applied: true}, nil)

	env.ExecuteWorkflow(zzTTLWorkflow)
	err := env.GetWorkflowError()
	t.Logf("completed=%v err=%v", env.IsWorkflowCompleted(), err)
	if err != nil {
		t.Fatalf("probe workflow failed: %v", err)
	}
}
