func zzAPITestWorkflow(ctx workflow.Context) error {
	f := workflow.NewTimer(ctx, time.Hour)
	t := reflect.TypeOf(f)
	lg := workflow.GetLogger(ctx)
	lg.Info("probe: future type=" + t.String())
	for i := 0; i < t.NumMethod(); i++ {
		lg.Info("probe: future method=" + t.Method(i).Name)
	}
	ch := workflow.GetSignalChannel(ctx, "X")
	ct := reflect.TypeOf(ch)
	lg.Info("probe: channel type=" + ct.String())
	for i := 0; i < ct.NumMethod(); i++ {
		lg.Info("probe: channel method=" + ct.Method(i).Name)
	}
	return nil
}

// TestZZAPIProbe documents the concurrency surface available in this SDK
// build.
func TestZZAPIProbe(t *testing.T) {
	env := newTestEnv()
	env.SetTestTimeout(5 * time.Second)
	env.ExecuteWorkflow(zzAPITestWorkflow)
	t.Logf("err=%v", env.GetWorkflowError())
}
