	if err := workflow.ExecuteActivity(ctx, activities.PublishFulfillment,
		shared.PublishFulfillmentInput{Order: order, Payment: &payment}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}

