	if err := workflow.ExecuteActivity(ctx, activities.UpdateDashboard,
		shared.UpdateDashboardInput{OrderId: orderID, Status: shared.StatusFulfilled}).Get(ctx, nil); err != nil {
		return shared.OrderProcessingResult{}, err
	}

