// Upsert implements DashboardWriter.
func (w *SQLDashboardWriter) Upsert(orderId string, status shared.OrderStatus, updatedAt time.Time) error {
	res, err := w.db.Exec(
		"UPDATE orders_dashboard SET status = ?, updated_at = ? WHERE order_id = ?",
